parameters.inputSchema:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "ProposalOutput",
  "type": "object",
  "required": ["summaryHtml", "confidenceScore", "proposalGood"],
  "properties": {
    "summaryHtml": {
      "type": "string",
      "description": "HTML-formatted summary of the proposal. Must be valid HTML or plain text wrapped in HTML tags."
    },
    "confidenceScore": {
      "type": "number",
      "minimum": 0,
      "maximum": 100,
      "description": "Score from 0 to 100 representing how strong or persuasive the proposal is."
    },
    "proposalGood": {
      "type": "boolean",
      "description": "Boolean indicating whether the proposal is strong enough to send (true if confidenceScore >= 60)."
    }
  },
  "additionalProperties": false
}

parameters.jsCode:
const primaryEmail = $('Extract Booking Details').first().json.hostEmail;
const ccEmailList = ["hi@thesohailjafri.me"];
const bccEmailList = [""];

// Convert lists to comma-separated strings with clean filtering
const ccString = ccEmailList.filter(Boolean).join(",");
const bccString = bccEmailList.filter(Boolean).join(",");

// Check if each one has valid values
const hasPrimary = Boolean(primaryEmail);
const hasCC = ccString.length > 0;
const hasBCC = bccString.length > 0;

return { primaryEmail, ccString, bccString, hasPrimary, hasCC, hasBCC }

